 92→func waitForApproval(ctx context.Context, poller deviceAuthClient, deviceCode string, expiresIn, interval int) (string, error) {
 93→	expiry := time.Duration(expiresIn) * time.Second
 94→	if expiry <= 0 || expiry > maxExpiresIn {
 95→		expiry = maxExpiresIn
 96→	}
 97→	deadline := time.Now().Add(expiry)
 98→	pollInterval := time.Duration(interval) * time.Second
 99→	if pollInterval <= 0 {
100→		pollInterval = fallbackDeviceAuthPollInterval
101→	}
102→
103→	consecutiveErrors := 0
104→
105→	for {
106→		if time.Now().After(deadline) {
107→			return "", errors.New("device authorization expired")
108→		}
109→
110→		result, err := poller.PollDeviceAuth(ctx, deviceCode)
111→		if err != nil {
112→			consecutiveErrors++
113→			if consecutiveErrors >= maxTransientErrors {
114→				return "", fmt.Errorf("poll approval status (after %d consecutive failures): %w", consecutiveErrors, err)
115→			}
116→			// Transient error — wait and retry.
117→			select {
118→			case <-ctx.Done():
119→				return "", fmt.Errorf("wait for approval: %w", ctx.Err())
120→			case <-time.After(pollInterval):
121→			}
122→			continue
123→		}
124→		consecutiveErrors = 0
125→
126→		switch result.Error {
127→		case "":
128→			if result.AccessToken == "" {
129→				return "", errors.New("device authorization completed without a token")
130→			}
131→			return result.AccessToken, nil
132→		case "authorization_pending":
133→			// no-op, will sleep and retry below
134→		case "slow_down":
135→			pollInterval += slowDownBackoff
136→			if pollInterval > maxPollInterval {
137→				pollInterval = maxPollInterval
138→			}
139→		case "access_denied":
140→			return "", errors.New("device authorization denied")
141→		case "expired_token":
142→			return "", errors.New("device authorization expired")
143→		default:
144→			return "", fmt.Errorf("device authorization failed: %s", result.Error)
145→		}
146→
147→		select {
148→		case <-ctx.Done():
149→			return "", fmt.Errorf("wait for approval: %w", ctx.Err())
150→		case <-time.After(pollInterval):
151→		}
152→	}
153→}
