155→func openBrowser(ctx context.Context, browserURL string) error {
156→	u, err := url.Parse(browserURL)
157→	if err != nil || (u.Scheme != "https" && u.Scheme != "http") {
158→		return fmt.Errorf("refusing to open non-HTTP URL: %s", browserURL)
159→	}
160→
161→	var command string
162→	var args []string
163→
164→	switch runtime.GOOS {
165→	case "darwin":
166→		command = "open"
167→		args = []string{browserURL}
168→	case "linux":
169→		command = "xdg-open"
170→		args = []string{browserURL}
171→	case "windows":
172→		command = "cmd"
173→		args = []string{"/c", "start", "", browserURL}
174→	default:
175→		return fmt.Errorf("unsupported platform %s", runtime.GOOS)
176→	}
177→
178→	cmd := exec.CommandContext(ctx, command, args...)
179→	if err := cmd.Start(); err != nil {
180→		return fmt.Errorf("start browser command %q: %w", command, err)
181→	}
182→
183→	if err := cmd.Process.Release(); err != nil {
184→		return fmt.Errorf("release browser process: %w", err)
185→	}
186→
187→	return nil
188→}
